CREATE TABLE IF NOT EXISTS bookings (
  id bigserial PRIMARY KEY,
  staff text NOT NULL,
  customer_name text NOT NULL,
  customer_email text NOT NULL,
  starts_at timestamptz NOT NULL,
  ends_at timestamptz NOT NULL,
  notes text,
  status text NOT NULL DEFAULT 'confirmed',
  confirmation_error text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS bookings_one_per_staff_slot ON bookings (staff, starts_at) WHERE status = 'confirmed';
CREATE UNIQUE INDEX IF NOT EXISTS bookings_one_per_customer_slot ON bookings (customer_email, starts_at) WHERE status = 'confirmed';
CREATE INDEX IF NOT EXISTS bookings_start ON bookings (starts_at);
CREATE OR REPLACE FUNCTION n8n_book_first_free(p_name text, p_email text, p_start timestamptz, p_end timestamptz, p_notes text, p_staff text[])
RETURNS TABLE (booking_id bigint, staff text, existing_id bigint, existing_staff text)
LANGUAGE plpgsql AS $$
#variable_conflict use_column
DECLARE s text; v_id bigint;
BEGIN
  -- Each INSERT below sees bookings committed a moment ago, so a lost race on one staff member moves on to the next.
  SELECT b.id, b.staff INTO existing_id, existing_staff FROM bookings b
  WHERE b.customer_email = p_email AND b.starts_at = p_start AND b.status = 'confirmed' LIMIT 1;
  IF existing_id IS NOT NULL THEN RETURN NEXT; RETURN; END IF;
  FOREACH s IN ARRAY p_staff LOOP
    v_id := NULL;
    INSERT INTO bookings (staff, customer_name, customer_email, starts_at, ends_at, notes)
    VALUES (s, p_name, p_email, p_start, p_end, p_notes)
    ON CONFLICT DO NOTHING RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN booking_id := v_id; staff := s; RETURN NEXT; RETURN; END IF;
  END LOOP;
  SELECT b.id, b.staff INTO existing_id, existing_staff FROM bookings b
  WHERE b.customer_email = p_email AND b.starts_at = p_start AND b.status = 'confirmed' LIMIT 1;
  RETURN NEXT;
END $$;

