// Check the request and work out which staff could take this slot.
const s = $input.first().json;
const zone = $now.zoneName;
const fail = (error) => [{ json: { valid: false, error } }];
const email = String(s.Email || '').trim().toLowerCase();
const name = String(s.Name || '').trim();
if (!name) return fail('Please enter your name.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail('Please enter a valid email address.');
const start = DateTime.fromISO(String(s.Date) + 'T' + String(s.Time), { zone });
if (!start.isValid) return fail('Please choose a valid date and time.');
const slot = Number(s.slot_minutes) || 60;
const end = start.plus({ minutes: slot });
if (start < $now) return fail('That time has already passed. Please choose a future date.');
if (start < $now.plus({ hours: Number(s.min_notice_hours) || 0 })) return fail('That time is too soon. Bookings need at least ' + (Number(s.min_notice_hours) || 0) + ' hours notice.');
if (start > $now.plus({ days: Number(s.max_days_ahead) || 60 })) return fail('That date is too far ahead. You can book up to ' + (Number(s.max_days_ahead) || 60) + ' days in advance.');
const staff = Array.isArray(s.staff) ? s.staff : [];
const day = start.toFormat('ccc');
const eligible = staff.filter((p) => {
  if (!(p.days || []).includes(day)) return false;
  const open = DateTime.fromISO(start.toISODate() + 'T' + p.start, { zone });
  const close = DateTime.fromISO(start.toISODate() + 'T' + p.end, { zone });
  if (start < open || end > close) return false;
  return Math.round(start.diff(open, 'minutes').minutes) % slot === 0;
}).map((p) => p.name);
if (!eligible.length) return fail('Nobody works at ' + start.toFormat('cccc d LLLL, HH:mm') + '. Please choose another time.');
return [{ json: {
  valid: true, name, email, notes: String(s.Notes || '').slice(0, 1000),
  starts_at: start.toUTC().toISO(), ends_at: end.toUTC().toISO(),
  when: start.toFormat('cccc d LLLL yyyy, HH:mm') + ' (' + start.toFormat('ZZZZ') + ')',
  eligible_staff: eligible,
} }];

// Next free times (any staff) from the requested day onward, using the same rules as Validate Request.
const s = $('Booking Settings').first().json;
const req = $('Validate Request').first().json;
const zone = $now.zoneName;
const slot = Number(s.slot_minutes) || 60;
const earliest = $now.plus({ hours: Number(s.min_notice_hours) || 0 });
const latest = $now.plus({ days: Number(s.max_days_ahead) || 60 });
const booked = new Set($input.all().map((i) => i.json).filter((b) => b.staff).map((b) => b.staff + '|' + DateTime.fromISO(String(b.starts_at)).toUTC().toISO()));
const found = [];
let day = DateTime.fromISO(req.starts_at).setZone(zone).startOf('day');
for (let d = 0; d < 14 && found.length < 5; d++, day = day.plus({ days: 1 })) {
  const times = new Map();
  for (const p of s.staff || []) {
    if (!(p.days || []).includes(day.toFormat('ccc'))) continue;
    const close = DateTime.fromISO(day.toISODate() + 'T' + p.end, { zone });
    for (let t = DateTime.fromISO(day.toISODate() + 'T' + p.start, { zone }); t.plus({ minutes: slot }) <= close; t = t.plus({ minutes: slot })) {
      if (t < earliest || t > latest || booked.has(p.name + '|' + t.toUTC().toISO())) continue;
      times.set(t.toMillis(), t);
    }
  }
  for (const t of [...times.values()].sort((a, b) => a - b)) { if (found.length < 5) found.push(t.toFormat('ccc d LLL, HH:mm')); }
}
return [{ json: { suggestions: found.length ? found.join(' | ') : 'no free times in the next two weeks' } }];
